BANK.push(
/* ── 8 · Кадастры ────────────────────────────────────────────────────────── */
{ id: `cad-1`, module: `cadastre`, diff: `easy`, type: `concept`, correct: 2,
  ru: { q: `Что такое кадастр?`,
    o: [`Карта местности с границами районов`, `Перечень цен по сделкам с недвижимостью`, `Систематизированный свод количественных, качественных, правовых и стоимостных сведений об объектах`, `Налоговый кодекс в части имущественных налогов`],
    ex: `Кадастр объединяет четыре группы сведений: сколько (площадь, объём), какого качества (бонитет, категория), чьё и с какими ограничениями (правовой статус), сколько стоит (кадастровая стоимость). Карта — лишь одна из его частей.`,
    why: [`Карта — графическая часть кадастра, но не весь кадастр.`, `Цены сделок — рыночная информация, а не кадастр.`, `Верно: кадастр — комплексный свод сведений.`, `Налоговые нормы используют кадастровые данные, но кадастром не являются.`],
    trick: `Кадастр отвечает на 4 вопроса: сколько, какое, чьё, почём.`, mistake: `Сводить кадастр к карте.`, takeaway: `Кадастр делает ресурс измеримым для учёта, налогов и анализа.` },
  en: { q: `What is a cadastre?`,
    o: [`A map showing district boundaries`, `A list of real-estate transaction prices`, `A systematic register of quantitative, qualitative, legal and value information about objects`, `The property-tax section of the tax code`],
    ex: `A cadastre brings together four kinds of data: how much (area, volume), what quality (soil rating, category), whose and with what restrictions (legal status), and what it is worth (cadastral value). A map is only one part.`,
    why: [`A map is the graphical part of a cadastre, not the whole.`, `Transaction prices are market information, not a cadastre.`, `Correct: a cadastre is a comprehensive register.`, `Tax rules use cadastral data but are not a cadastre.`],
    trick: `A cadastre answers four questions: how much, what kind, whose, worth what.`, mistake: `Reducing a cadastre to a map.`, takeaway: `A cadastre makes a resource measurable for accounting, tax and analysis.` } },
{ id: `cad-2`, module: `cadastre`, diff: `easy`, type: `concept`, correct: 0,
  ru: { q: `Что характеризует бонитет почв?`,
    o: [`Качество и плодородие почвы в баллах`, `Правовой статус земельного участка`, `Рыночную цену гектара`, `Площадь участка`],
    ex: `Бонитировка — оценка почв по плодородию в баллах (лучшие почвы — 100). Она позволяет сравнивать участки по качеству и учитывать его при оценке.`,
    why: [`Верно: бонитет — показатель качества.`, `Правовой статус — правовой индикатор кадастра.`, `Цена — стоимостной показатель.`, `Площадь — количественный показатель.`],
    trick: `Бонитет — «оценка» почвы, как школьная, только по 100-балльной шкале.`, mistake: `Путать качественные и стоимостные индикаторы.`, takeaway: `Одинаковая площадь не означает одинаковый потенциал — важно качество.` },
  en: { q: `What does a soil rating (bonitet) describe?`,
    o: [`Soil quality and fertility in points`, `The legal status of a plot`, `The market price per hectare`, `The plot’s area`],
    ex: `Soil rating scores soils for fertility in points (the best soils score 100). It allows plots to be compared by quality and that quality to be reflected in valuation.`,
    why: [`Correct: the rating is a quality indicator.`, `Legal status is a legal indicator.`, `Price is a value indicator.`, `Area is a quantity indicator.`],
    trick: `A soil rating is like a school grade, only out of 100.`, mistake: `Mixing up quality and value indicators.`, takeaway: `The same area does not mean the same potential — quality matters.` } },
{ id: `cad-3`, module: `cadastre`, diff: `medium`, type: `calc`, correct: 1,
  ru: { q: `Площадь участка — 3,2 га, удельный показатель кадастровой стоимости — 25 млн сум за гектар. Какова кадастровая стоимость участка?`,
    o: [`7,8 млн сум`, `80 млн сум`, `28,2 млн сум`, `800 млн сум`],
    ex: `КС = Площадь × УПКС = 3,2 × 25 = 80 млн сум.`,
    why: [`УПКС разделён на площадь — неверная операция.`, `Верно: 3,2 × 25 = 80.`, `Площадь и показатель сложены.`, `Ошибка на порядок.`],
    trick: `Удельный показатель — «цена одного гектара».`, mistake: `Делить вместо умножения.`, takeaway: `Кадастровая стоимость = площадь × удельный показатель.` },
  en: { q: `A plot covers 3.2 ha; the unit cadastral value is 25 m soums per hectare. What is the plot’s cadastral value?`,
    o: [`7.8 m soums`, `80 m soums`, `28.2 m soums`, `800 m soums`],
    ex: `CV = Area × Unit value = 3.2 × 25 = 80 m soums.`,
    why: [`The unit value was divided by the area.`, `Correct: 3.2 × 25 = 80.`, `Area and unit value were added.`, `An order-of-magnitude error.`],
    trick: `The unit value is “the price of one hectare”.`, mistake: `Dividing instead of multiplying.`, takeaway: `Cadastral value = area × unit value.` } },
{ id: `cad-4`, module: `cadastre`, diff: `medium`, type: `compare`, correct: 3,
  ru: { q: `Чем кадастровая стоимость отличается от рыночной?`,
    o: [`Они всегда совпадают по закону`, `Кадастровая всегда выше рыночной`, `Рыночная стоимость определяется государством, кадастровая — продавцом`, `Кадастровую определяют массовой государственной оценкой по единой методике, рыночная — вероятная цена конкретной сделки; они могут не совпадать`],
    ex: `Кадастровая стоимость рассчитывается для множества объектов сразу по единой методике и служит базой для налогов и платежей. Рыночная отражает спрос и предложение на конкретный объект в момент сделки. Расхождения нормальны и могут быть в обе стороны.`,
    why: [`Закон не требует их совпадения.`, `Соотношение может быть любым.`, `Роли перепутаны.`, `Верно: различие в методе и назначении.`],
    trick: `Кадастровая — «для государства», рыночная — «для сделки».`, mistake: `Использовать кадастровую стоимость как цену продажи.`, takeaway: `Для анализа налоговой нагрузки — кадастровая, для инвестиций — рыночная.` },
  en: { q: `How does cadastral value differ from market value?`,
    o: [`By law they are always equal`, `Cadastral value is always higher`, `The state sets market value; the seller sets cadastral value`, `Cadastral value comes from mass state assessment using one method; market value is the likely price of a specific deal; they may differ`],
    ex: `Cadastral value is calculated for many objects at once with one method and is the base for taxes and charges. Market value reflects supply and demand for a specific object at the time of a deal. Differences are normal and can go either way.`,
    why: [`The law does not require them to match.`, `The relationship can go either way.`, `The roles are reversed.`, `Correct: they differ in method and purpose.`],
    trick: `Cadastral — “for the state”; market — “for the deal”.`, mistake: `Using cadastral value as a sale price.`, takeaway: `Use cadastral value for tax burden, market value for investment.` } },
{ id: `cad-5`, module: `cadastre`, diff: `hard`, type: `compare`, correct: 2,
  ru: { q: `Два участка по 50 га. Бонитет участка А — 80 баллов, участка Б — 50 баллов; средний балл по району — 64. Какой вывод обоснован?`,
    o: [`Потенциалы равны, поскольку площади одинаковы`, `Участок Б лучше, так как его балл ближе к среднему`, `Участок А на 25% лучше среднего по району, Б — примерно на 22% хуже; при равной площади природно-ресурсный потенциал А выше`, `Сравнивать можно только по кадастровой стоимости`],
    ex: `Индекс качества: А = 80 / 64 = 1,25; Б = 50 / 64 ≈ 0,78. При одинаковой площади урожайность и доходность на участке А ожидаемо выше, что должно учитываться в оценке и планировании.`,
    why: [`Площадь — только количественная сторона.`, `Близость к среднему не делает землю лучше.`, `Верно: 1,25 против 0,78.`, `Качественные индикаторы вполне пригодны для сравнения.`],
    trick: `Площадь × качество = потенциал.`, mistake: `Сравнивать землю только по гектарам.`, takeaway: `Качественные индикаторы кадастра так же важны, как количественные.` },
  en: { q: `Two plots of 50 ha each. Plot A has a soil rating of 80, plot B of 50; the district average is 64. Which conclusion is justified?`,
    o: [`Their potential is equal because their areas are equal`, `Plot B is better because its score is closer to average`, `Plot A is 25% above the district average and B about 22% below; with equal areas, A has higher natural-resource potential`, `They can be compared only by cadastral value`],
    ex: `Quality index: A = 80 / 64 = 1.25; B = 50 / 64 ≈ 0.78. With equal areas, yields and returns on A are expected to be higher, which should be reflected in valuation and planning.`,
    why: [`Area is only the quantitative side.`, `Being close to average does not make land better.`, `Correct: 1.25 versus 0.78.`, `Quality indicators are perfectly usable for comparison.`],
    trick: `Area × quality = potential.`, mistake: `Comparing land by hectares alone.`, takeaway: `Qualitative cadastral indicators matter as much as quantitative ones.` } },
{ id: `cad-6`, module: `cadastre`, diff: `expert`, type: `cause`, correct: 0,
  ru: { q: `После переоценки кадастровая стоимость земли предприятия выросла на 40%, а рыночная практически не изменилась. Как это отразится на анализе?`,
    o: [`Вырастут платежи, исчисляемые от кадастровой стоимости, и налоговая нагрузка; при этом рыночная (залоговая и инвестиционная) ценность земли и доходы от неё не изменились`, `Предприятие стало богаче на 40%`, `Вырастут доходы от использования земли`, `Ничего не изменится: кадастровая стоимость не используется в расчётах`],
    ex: `Кадастровая стоимость — база для ряда налогов и платежей, поэтому её рост увеличивает расходы. Но реальная ценность актива для сделки и доход от его использования определяются рынком и производительностью земли, а они не изменились. Итог — снижение рентабельности использования земли.`,
    why: [`Верно: растут расходы, а не ценность и доходы.`, `Рост оценочной базы не означает роста богатства.`, `Доходы зависят от использования земли, а не от её оценки.`, `Кадастровая стоимость прямо используется как налоговая база.`],
    trick: `Кадастр влияет на то, сколько платить, а не на то, сколько зарабатывать.`, mistake: `Отождествлять рост кадастровой оценки с ростом стоимости бизнеса.`, takeaway: `Изменение кадастровой стоимости анализируют через налоговую нагрузку.` },
  en: { q: `After revaluation, the cadastral value of a company’s land rose 40%, while its market value barely changed. How does this affect the analysis?`,
    o: [`Charges based on cadastral value and the tax burden rise, while the market (collateral and investment) value of the land and the income it produces are unchanged`, `The company has become 40% richer`, `Income from using the land will rise`, `Nothing changes: cadastral value is not used in any calculation`],
    ex: `Cadastral value is the base for several taxes and charges, so its growth raises costs. The real value of the asset in a deal and the income from using it depend on the market and the land’s productivity, which have not changed. The result is lower profitability of land use.`,
    why: [`Correct: costs rise, not value or income.`, `A higher assessment base does not mean more wealth.`, `Income depends on how the land is used, not how it is assessed.`, `Cadastral value is used directly as a tax base.`],
    trick: `The cadastre affects how much you pay, not how much you earn.`, mistake: `Equating a higher cadastral assessment with a more valuable business.`, takeaway: `Analyse changes in cadastral value through the tax burden.` } },

/* ── 9 · Трудовой потенциал ──────────────────────────────────────────────── */
{ id: `lab-1`, module: `labour`, diff: `easy`, type: `concept`, correct: 1,
  ru: { q: `Кто учитывается при расчёте коэффициента текучести кадров?`,
    o: [`Все выбывшие работники`, `Уволенные по собственному желанию и за нарушения трудовой дисциплины`, `Ушедшие на пенсию и призванные в армию`, `Принятые на работу за период`],
    ex: `Текучесть — «излишний» оборот, вызванный неудовлетворённостью работой или нарушениями. Выбытие по объективным причинам (пенсия, призыв, окончание договора) в текучесть не включают — оно не зависит от политики управления персоналом.`,
    why: [`Все выбывшие — основа коэффициента выбытия, а не текучести.`, `Верно: это «управляемая» часть выбытия.`, `Это объективные причины выбытия.`, `Приём — основа коэффициента оборота по приёму.`],
    trick: `Текучесть — те, кто ушёл, «потому что захотел или пришлось за дело».`, mistake: `Включать в текучесть все увольнения.`, takeaway: `Текучесть показывает проблемы мотивации и условий труда.` },
  en: { q: `Who is counted in the staff turnover (attrition) rate?`,
    o: [`All leavers`, `Those who left voluntarily or were dismissed for misconduct`, `Retirees and conscripts`, `Those hired during the period`],
    ex: `Turnover is the “excess” movement caused by dissatisfaction or misconduct. Leaving for objective reasons (retirement, conscription, end of contract) is excluded — it does not depend on HR policy.`,
    why: [`All leavers form the leaving rate, not turnover.`, `Correct: this is the “manageable” part of leaving.`, `These are objective reasons for leaving.`, `Hires form the hiring rate.`],
    trick: `Turnover — those who left “because they wanted to, or had to for cause”.`, mistake: `Counting every departure as turnover.`, takeaway: `Turnover reveals problems with motivation and working conditions.` } },
{ id: `lab-2`, module: `labour`, diff: `easy`, type: `compare`, correct: 3,
  ru: { q: `Как связаны выработка и трудоёмкость?`,
    o: [`Это одинаковые показатели`, `Выработка — затраты времени на изделие, трудоёмкость — продукция на работника`, `Они не связаны между собой`, `Выработка — продукция на единицу времени или работника, трудоёмкость — затраты времени на единицу продукции; показатели обратны`],
    ex: `Выработка и трудоёмкость — прямой и обратный показатели производительности. Если выработка растёт на 25%, трудоёмкость снижается на 20% (1 / 1,25 = 0,8).`,
    why: [`Это разные, хотя и связанные показатели.`, `Определения перепутаны.`, `Связь обратная и строгая.`, `Верно: прямой и обратный показатели.`],
    trick: `Выработка — «сколько сделал», трудоёмкость — «сколько потратил».`, mistake: `Считать, что рост выработки на 25% снижает трудоёмкость на 25%.`, takeaway: `Снижение трудоёмкости — главный путь роста выработки.` },
  en: { q: `How are output per worker and labour intensity related?`,
    o: [`They are the same indicator`, `Output per worker is time per unit; labour intensity is output per worker`, `They are unrelated`, `Output is production per unit of time or per worker; labour intensity is time per unit of output; they are inverse`],
    ex: `Output and labour intensity are the direct and inverse measures of productivity. If output rises 25%, labour intensity falls 20% (1 / 1.25 = 0.8).`,
    why: [`They are different, though linked.`, `The definitions are swapped.`, `The link is strictly inverse.`, `Correct: direct and inverse measures.`],
    trick: `Output — “how much was made”; intensity — “how much time it took”.`, mistake: `Thinking a 25% rise in output cuts intensity by 25%.`, takeaway: `Cutting labour intensity is the main route to higher output.` } },
{ id: `lab-3`, module: `labour`, diff: `medium`, type: `calc`, correct: 0,
  ru: { q: `Среднесписочная численность — 400 человек. Принято 48, выбыло 40, в том числе по собственному желанию — 22, за нарушения — 6. Каков коэффициент текучести?`,
    o: [`7,0%`, `10,0%`, `12,0%`, `5,5%`],
    ex: `Kтек = (22 + 6) / 400 = 7,0%. Остальные 12 выбывших ушли по объективным причинам и в текучесть не входят.`,
    why: [`Верно: (22 + 6) / 400.`, `10% — коэффициент выбытия (40 / 400).`, `12% — коэффициент оборота по приёму (48 / 400).`, `Не учтены уволенные за нарушения.`],
    trick: `Текучесть ≤ выбытие — всегда.`, mistake: `Подставлять всех выбывших.`, takeaway: `Делите на среднесписочную численность, а не на численность на дату.` },
  en: { q: `Average headcount is 400. 48 were hired and 40 left, including 22 voluntarily and 6 dismissed for misconduct. What is the turnover rate?`,
    o: [`7.0%`, `10.0%`, `12.0%`, `5.5%`],
    ex: `Kt = (22 + 6) / 400 = 7.0%. The other 12 leavers left for objective reasons and are excluded.`,
    why: [`Correct: (22 + 6) / 400.`, `10% is the leaving rate (40 / 400).`, `12% is the hiring rate (48 / 400).`, `Dismissals for misconduct were left out.`],
    trick: `Turnover ≤ leaving rate — always.`, mistake: `Using all leavers.`, takeaway: `Divide by average headcount, not headcount at a date.` } },
{ id: `lab-4`, module: `labour`, diff: `medium`, type: `calc`, correct: 2,
  ru: { q: `Численность рабочих — 50 человек, каждый отработал в среднем 220 дней по 7,8 часа. Каков фонд рабочего времени?`,
    o: [`11 000 чел.-дней`, `85 800 часов на человека`, `85 800 чел.-часов`, `1 716 чел.-часов`],
    ex: `ФРВ = Ч × Д × П = 50 × 220 × 7,8 = 85 800 человеко-часов. 11 000 — фонд в человеко-днях, а не в часах.`,
    why: [`Это фонд в человеко-днях (без учёта длины смены).`, `Единица измерения неверна — это фонд всего коллектива.`, `Верно: 50 × 220 × 7,8.`, `Пропущена численность.`],
    trick: `Люди × дни × часы.`, mistake: `Терять один из трёх множителей.`, takeaway: `Потери рабочего времени ищут по каждому множителю: дни и часы.` },
  en: { q: `There are 50 workers; each worked on average 220 days of 7.8 hours. What is the working-time fund?`,
    o: [`11,000 person-days`, `85,800 hours per person`, `85,800 person-hours`, `1,716 person-hours`],
    ex: `WTF = H × D × h = 50 × 220 × 7.8 = 85,800 person-hours. 11,000 is the fund in person-days, not hours.`,
    why: [`That is the fund in person-days (ignores shift length).`, `Wrong unit — this is the fund for the whole team.`, `Correct: 50 × 220 × 7.8.`, `Headcount was left out.`],
    trick: `People × days × hours.`, mistake: `Dropping one of the three factors.`, takeaway: `Working-time losses are traced through each factor: days and hours.` } },
{ id: `lab-5`, module: `labour`, diff: `hard`, type: `cause`, correct: 1,
  ru: { q: `Выработка на одного работника выросла на 6%, средняя заработная плата — на 10%. Какой вывод обоснован?`,
    o: [`Ситуация благоприятная: оба показателя растут`, `Коэффициент опережения ≈ 0,96 < 1: оплата труда растёт быстрее производительности, затраты на оплату труда на единицу продукции увеличиваются`, `Коэффициент опережения ≈ 1,04 — производительность опережает зарплату`, `Вывод невозможен без данных о прибыли`],
    ex: `Kоп = Iвыр / Iзп = 1,06 / 1,10 ≈ 0,964. Если оплата труда растёт быстрее выработки, на каждый сум продукции приходится больше затрат на зарплату — себестоимость растёт, прибыль под давлением.`,
    why: [`Важно не направление, а соотношение темпов.`, `Верно: Kоп < 1 — тревожный сигнал.`, `Индексы поставлены в обратном порядке.`, `Вывод о затратах на единицу делается по соотношению индексов.`],
    trick: `«Сначала заработай, потом получи»: выработка должна расти быстрее зарплаты.`, mistake: `Радоваться росту обоих показателей, не сравнивая темпы.`, takeaway: `Опережающий рост производительности — условие снижения себестоимости.` },
  en: { q: `Output per worker rose 6% and the average wage rose 10%. Which conclusion is justified?`,
    o: [`Favourable: both indicators are rising`, `The outpacing ratio ≈ 0.96 < 1: pay is growing faster than productivity, so labour cost per unit rises`, `The outpacing ratio ≈ 1.04 — productivity outpaces pay`, `No conclusion is possible without profit data`],
    ex: `Ko = I_output / I_wage = 1.06 / 1.10 ≈ 0.964. If pay grows faster than output, each soum of output carries more labour cost — unit cost rises and profit comes under pressure.`,
    why: [`What matters is not the direction but the ratio of rates.`, `Correct: Ko < 1 is a warning sign.`, `The indices are inverted.`, `Unit labour cost follows from the ratio of indices.`],
    trick: `“Earn first, then get paid”: output must outpace wages.`, mistake: `Welcoming growth in both without comparing rates.`, takeaway: `Productivity outpacing pay is a condition for lower unit costs.` } },
{ id: `lab-6`, module: `labour`, diff: `expert`, type: `case`, correct: 3,
  ru: { q: `Среднечасовая выработка рабочего выросла на 8%, а среднегодовая выработка одного работающего не изменилась. Какое объяснение согласуется с моделью ГВ = Уд × Д × П × ЧВ?`,
    o: [`Ошибка в расчётах: рост часовой выработки обязательно повышает годовую`, `Выросла численность — это снижает выработку`, `Цены на продукцию снизились на 8%`, `Снизились другие факторы: доля рабочих в численности (Уд), число отработанных дней (Д) или продолжительность смены (П) — например, выросли простои или непроизводственный персонал`],
    ex: `ГВ — произведение четырёх факторов. Если ЧВ выросла на 8%, а ГВ не изменилась, произведение Уд × Д × П снизилось примерно на 7,4% (1 / 1,08). Причины: рост доли управленческого и вспомогательного персонала, целодневные потери (прогулы, болезни, простои) или внутрисменные потери времени.`,
    why: [`Противоречия нет — другие множители могли снизиться.`, `Численность сама по себе не входит в эту модель — важна доля рабочих.`, `Цены не меняют натуральную выработку; дело в факторах времени и структуры.`, `Верно: рост интенсивного фактора съеден потерями экстенсивных.`],
    trick: `Рабочий стал работать быстрее, но реже или его стало «меньше в штате».`, mistake: `Искать ошибку счёта вместо анализа других факторов.`, takeaway: `Многофакторная модель показывает, где теряется рост производительности.` },
  en: { q: `Hourly output per worker rose 8%, but annual output per employee did not change. Which explanation fits the model AO = Sh × D × h × HO?`,
    o: [`A calculation error: higher hourly output must raise annual output`, `Headcount rose, which lowers output`, `Product prices fell 8%`, `Other factors fell: the share of production workers (Sh), days worked (D) or shift length (h) — e.g. more downtime or more non-production staff`],
    ex: `AO is the product of four factors. If HO rose 8% and AO did not change, Sh × D × h fell by about 7.4% (1 / 1.08). Causes: a larger share of managerial and support staff, whole-day losses (absences, illness, downtime) or intra-shift time losses.`,
    why: [`There is no contradiction — other factors could have fallen.`, `Headcount alone is not in this model — the share of workers is.`, `The issue lies in time and structure factors, not prices.`, `Correct: the gain in the intensive factor was eaten by losses in the extensive ones.`],
    trick: `Workers got faster, but worked less often — or became a smaller share of staff.`, mistake: `Looking for an arithmetic error instead of analysing the other factors.`, takeaway: `A multi-factor model shows where productivity gains are lost.` } },

/* ── 10 · Финансовый потенциал ───────────────────────────────────────────── */
{ id: `fp-1`, module: `finpot`, diff: `easy`, type: `concept`, correct: 2,
  ru: { q: `Как рассчитывается рентабельность собственного капитала (ROE)?`,
    o: [`Чистая прибыль / Активы`, `Выручка / Собственный капитал`, `Чистая прибыль / Собственный капитал`, `Собственный капитал / Валюта баланса`],
    ex: `ROE показывает, сколько чистой прибыли приходится на сум средств собственников. ЧП / Активы — ROA, Выручка / СК — оборачиваемость капитала, СК / ВБ — коэффициент автономии.`,
    why: [`Это рентабельность активов (ROA).`, `Это оборачиваемость собственного капитала.`, `Верно.`, `Это коэффициент автономии.`],
    trick: `ROE — «Return on Equity»: прибыль собственников на их капитал.`, mistake: `Путать ROE и ROA.`, takeaway: `ROE — главный ориентир для собственников.` },
  en: { q: `How is return on equity (ROE) calculated?`,
    o: [`Net profit / Assets`, `Revenue / Equity`, `Net profit / Equity`, `Equity / Total assets`],
    ex: `ROE shows net profit per soum of owners’ funds. NP / Assets is ROA, Revenue / Equity is equity turnover, Equity / Total assets is the autonomy ratio.`,
    why: [`That is ROA.`, `That is equity turnover.`, `Correct.`, `That is the autonomy ratio.`],
    trick: `Return on Equity — the owners’ profit on the owners’ capital.`, mistake: `Confusing ROE with ROA.`, takeaway: `ROE is the owners’ main benchmark.` } },
{ id: `fp-2`, module: `finpot`, diff: `easy`, type: `cause`, correct: 0,
  ru: { q: `При каком условии привлечение заёмных средств повышает рентабельность собственного капитала?`,
    o: [`Если экономическая рентабельность активов выше средней ставки процента по кредитам`, `Всегда, когда кредит получен`, `Если ставка процента выше рентабельности активов`, `Если кредит краткосрочный`],
    ex: `Заёмные средства работают на собственников, когда приносят больше, чем стоят. Положительный дифференциал (ЭР − ставка) даёт положительный эффект финансового рычага; отрицательный — снижает ROE.`,
    why: [`Верно: положительный дифференциал.`, `При дорогом кредите ROE снижается.`, `Это условие отрицательного эффекта.`, `Срок кредита не определяет знак эффекта.`],
    trick: `Занимай под 14%, если сам зарабатываешь 20%.`, mistake: `Считать, что долг всегда усиливает доходность.`, takeaway: `Знак рычага определяет дифференциал, а сила — плечо ЗК / СК.` },
  en: { q: `Under what condition does borrowing raise return on equity?`,
    o: [`When the economic return on assets exceeds the average interest rate`, `Whenever a loan is taken`, `When the interest rate exceeds the return on assets`, `When the loan is short-term`],
    ex: `Borrowed money works for owners when it earns more than it costs. A positive differential (ER − interest rate) gives a positive leverage effect; a negative one lowers ROE.`,
    why: [`Correct: a positive differential.`, `With an expensive loan ROE falls.`, `That is the condition for a negative effect.`, `The loan term does not set the sign of the effect.`],
    trick: `Borrow at 14% if you earn 20%.`, mistake: `Assuming debt always amplifies returns.`, takeaway: `The differential sets the sign of leverage; D / E sets its strength.` } },
{ id: `fp-3`, module: `finpot`, diff: `medium`, type: `calc`, correct: 1,
  ru: { q: `ЭР = 18%, средняя ставка по кредитам = 12%, ЗК / СК = 0,8, ставка налога на прибыль = 15%. Каков эффект финансового рычага?`,
    o: [`4,80%`, `4,08%`, `6,00%`, `5,10%`],
    ex: `ЭФР = (1 − 0,15) × (18% − 12%) × 0,8 = 0,85 × 6% × 0,8 = 4,08%. Заёмные средства повышают ROE на 4,08 п.п.`,
    why: [`Не учтён налоговый корректор (1 − Т).`, `Верно: 0,85 × 6 × 0,8.`, `Это только дифференциал.`, `Не учтено плечо (0,85 × 6).`],
    trick: `Три множителя: налоговый щит × дифференциал × плечо.`, mistake: `Забывать налоговый корректор.`, takeaway: `ЭФР растёт с плечом, но только пока дифференциал положителен.` },
  en: { q: `ER = 18%, average interest rate = 12%, D / E = 0.8, profit tax rate = 15%. What is the financial leverage effect?`,
    o: [`4.80%`, `4.08%`, `6.00%`, `5.10%`],
    ex: `FLE = (1 − 0.15) × (18% − 12%) × 0.8 = 0.85 × 6% × 0.8 = 4.08%. Borrowing lifts ROE by 4.08 p.p.`,
    why: [`The tax adjustment (1 − t) was left out.`, `Correct: 0.85 × 6 × 0.8.`, `That is only the differential.`, `The leverage ratio was left out (0.85 × 6).`],
    trick: `Three factors: tax shield × differential × leverage.`, mistake: `Forgetting the tax adjustment.`, takeaway: `FLE grows with leverage, but only while the differential is positive.` } },
{ id: `fp-4`, module: `finpot`, diff: `medium`, type: `calc`, correct: 3,
  ru: { q: `Рентабельность продаж — 10%, оборачиваемость активов — 1,5, мультипликатор капитала (Активы / СК) — 2. Чему равна ROE по модели Дюпона?`,
    o: [`13,5%`, `15%`, `20%`, `30%`],
    ex: `ROE = 10% × 1,5 × 2 = 30%. Рентабельность активов при этом 10% × 1,5 = 15%, а мультипликатор 2 удваивает её для собственников.`,
    why: [`Факторы сложены, а не перемножены.`, `15% — это ROA (без мультипликатора).`, `Пропущена оборачиваемость (10% × 2).`, `Верно: 10% × 1,5 × 2.`],
    trick: `Маржа × оборот × плечо.`, mistake: `Путать ROA и ROE в модели Дюпона.`, takeaway: `Модель Дюпона показывает, за счёт чего достигнута доходность.` },
  en: { q: `Return on sales is 10%, asset turnover 1.5, equity multiplier (Assets / Equity) 2. What is ROE by the DuPont model?`,
    o: [`13.5%`, `15%`, `20%`, `30%`],
    ex: `ROE = 10% × 1.5 × 2 = 30%. ROA is 10% × 1.5 = 15%, and the multiplier of 2 doubles it for owners.`,
    why: [`The factors were added, not multiplied.`, `15% is ROA (no multiplier).`, `Turnover was left out (10% × 2).`, `Correct: 10% × 1.5 × 2.`],
    trick: `Margin × turnover × leverage.`, mistake: `Confusing ROA and ROE in the DuPont model.`, takeaway: `DuPont shows what drives the return.` } },
{ id: `fp-5`, module: `finpot`, diff: `hard`, type: `case`, correct: 2,
  ru: { q: `Экономическая рентабельность активов компании — 11%, средняя ставка по кредитам — 16%. Руководство планирует увеличить долю заёмного капитала, чтобы «нарастить отдачу для акционеров». Какой вывод обоснован?`,
    o: [`Решение верное: рычаг всегда повышает ROE`, `Решение нейтрально: структура капитала на ROE не влияет`, `Решение ошибочно: дифференциал отрицателен (−5 п.п.), поэтому рост плеча снизит ROE и одновременно повысит финансовый риск`, `Решение верное, если кредит в иностранной валюте`],
    ex: `При ЭР ниже ставки каждый заёмный сум зарабатывает меньше, чем стоит. Эффект финансового рычага отрицателен, и чем больше плечо, тем сильнее он уменьшает ROE. Сначала нужно повысить рентабельность активов или найти более дешёвые источники.`,
    why: [`Рычаг работает в обе стороны.`, `Структура капитала прямо влияет на ROE через ЭФР.`, `Верно: отрицательный дифференциал превращает рычаг в «гирю».`, `Валюта кредита добавляет валютный риск, но не меняет логику.`],
    trick: `Рычаг — усилитель: он усиливает и прибыль, и убыток.`, mistake: `Наращивать долг при отрицательном дифференциале.`, takeaway: `Сначала проверьте знак дифференциала, потом — размер плеча.` },
  en: { q: `A company’s economic return on assets is 11% and its average interest rate is 16%. Management plans to raise the share of debt to “boost returns for shareholders”. Which conclusion is justified?`,
    o: [`The decision is right: leverage always raises ROE`, `The decision is neutral: capital structure does not affect ROE`, `The decision is wrong: the differential is negative (−5 p.p.), so more leverage will lower ROE and raise financial risk`, `The decision is right if the loan is in foreign currency`],
    ex: `With ER below the interest rate, every borrowed soum earns less than it costs. The leverage effect is negative, and the more leverage, the more it cuts ROE. First raise the return on assets or find cheaper funding.`,
    why: [`Leverage works both ways.`, `Capital structure directly affects ROE through leverage.`, `Correct: a negative differential turns leverage into a burden.`, `Currency adds FX risk but does not change the logic.`],
    trick: `Leverage is an amplifier — of profit and of loss.`, mistake: `Adding debt when the differential is negative.`, takeaway: `Check the sign of the differential first, then the size of leverage.` } },
{ id: `fp-6`, module: `finpot`, diff: `expert`, type: `compare`, correct: 0,
  ru: { q: `У двух компаний ROE = 24%. Компания А: рентабельность продаж 3%, оборачиваемость активов 4, мультипликатор 2. Компания Б: рентабельность продаж 12%, оборачиваемость 1, мультипликатор 2. Какой вывод наиболее обоснован?`,
    o: [`Одинаковая доходность достигнута разными моделями: А зарабатывает на обороте при низкой марже (торговая модель), Б — на высокой марже при медленном обороте; источники риска у них разные`, `Компании идентичны, поскольку ROE совпадает`, `Б однозначно лучше, потому что маржа выше`, `А однозначно лучше, потому что быстрее оборачивает активы`],
    ex: `Модель Дюпона раскрывает «ДНК» доходности. Для А опасно падение объёмов или маржи на 1–2 п.п. (маржа почти исчерпана), для Б — снижение цен или замедление продаж дорогих товаров. Одинаковый результат не означает одинаковых рисков и путей улучшения.`,
    why: [`Верно: разные драйверы — разные риски и резервы.`, `Совпадение итога скрывает различия в структуре.`, `Высокая маржа не лучше сама по себе — оборот у Б в 4 раза ниже.`, `Быстрый оборот не лучше сам по себе — маржа у А в 4 раза ниже.`],
    trick: `Один и тот же ROE можно «собрать» из разных кирпичей.`, mistake: `Сравнивать компании только по итоговому показателю.`, takeaway: `Разложение показателя важнее самого показателя.` },
  en: { q: `Two companies both have ROE = 24%. Company A: margin 3%, asset turnover 4, multiplier 2. Company B: margin 12%, turnover 1, multiplier 2. Which conclusion is best supported?`,
    o: [`The same return comes from different models: A earns on volume with a thin margin (a trading model), B on a high margin with slow turnover; their risks differ`, `The companies are identical, since ROE matches`, `B is clearly better because its margin is higher`, `A is clearly better because it turns assets faster`],
    ex: `DuPont reveals the “DNA” of returns. For A, a drop in volume or a 1–2 p.p. fall in margin is dangerous (the margin is nearly exhausted); for B, price cuts or slower sales of premium goods. The same result does not mean the same risks or improvement paths.`,
    why: [`Correct: different drivers mean different risks and reserves.`, `Matching totals hide structural differences.`, `A high margin is not better in itself — B’s turnover is four times lower.`, `Fast turnover is not better in itself — A’s margin is four times lower.`],
    trick: `The same ROE can be built from different bricks.`, mistake: `Comparing companies on the headline figure alone.`, takeaway: `The breakdown matters more than the indicator itself.` } },

/* ── 12 · Продукция ──────────────────────────────────────────────────────── */
{ id: `out-1`, module: `output`, diff: `easy`, type: `calc`, correct: 1,
  ru: { q: `Остаток готовой продукции на начало года — 200, выпуск товарной продукции — 5 000, остаток на конец года — 300 млн сум. Каков объём реализации?`,
    o: [`5 500 млн сум`, `4 900 млн сум`, `5 100 млн сум`, `5 000 млн сум`],
    ex: `РП = ГП нач + ТП − ГП кон = 200 + 5 000 − 300 = 4 900 млн сум. Рост остатков на складе означает, что реализация отстала от выпуска.`,
    why: [`Остатки сложены, а не учтены с разными знаками.`, `Верно: 200 + 5 000 − 300.`, `Знаки остатков перепутаны.`, `Выпуск не равен реализации, если остатки изменились.`],
    trick: `Что было + что сделали − что осталось = что продали.`, mistake: `Отождествлять выпуск и реализацию.`, takeaway: `Рост складских остатков — сигнал проблем со сбытом.` },
  en: { q: `Opening finished goods 200, marketable output 5,000, closing finished goods 300 m soums. What is the sales volume?`,
    o: [`5,500 m soums`, `4,900 m soums`, `5,100 m soums`, `5,000 m soums`],
    ex: `Sales = Opening FG + Output − Closing FG = 200 + 5,000 − 300 = 4,900 m soums. Rising stocks mean sales lagged behind output.`,
    why: [`Both balances were added instead of using opposite signs.`, `Correct: 200 + 5,000 − 300.`, `The signs of the balances are swapped.`, `Output is not sales when stocks change.`],
    trick: `What you had + what you made − what is left = what you sold.`, mistake: `Equating output with sales.`, takeaway: `Growing finished-goods stock signals a sales problem.` } },
{ id: `out-2`, module: `output`, diff: `easy`, type: `concept`, correct: 0,
  ru: { q: `Как оценивается выполнение плана по ассортименту способом наименьшего числа?`,
    o: [`По каждой позиции засчитывается фактический выпуск, но не выше плана`, `Засчитывается весь фактический выпуск по всем позициям`, `Засчитываются только позиции с перевыполнением плана`, `Сравнивается общий объём выпуска с общим планом`],
    ex: `Ассортимент — это обязательство выпустить нужные изделия. Перевыполнение по одной позиции не компенсирует недовыпуск другой: покупатель, которому нужна позиция Б, не возьмёт вместо неё лишнюю продукцию А.`,
    why: [`Верно: min(факт, план) по каждой позиции.`, `Перевыполнение не засчитывается.`, `Учитываются все позиции.`, `Это выполнение плана по объёму, а не по ассортименту.`],
    trick: `«Наименьшее из двух» — факт или план, что меньше.`, mistake: `Засчитывать перевыполнение.`, takeaway: `План по ассортименту не может быть выполнен больше чем на 100%.` },
  en: { q: `How is assortment plan fulfilment assessed by the lowest-number method?`,
    o: [`For each item, actual output is counted, but no more than plan`, `All actual output is counted for all items`, `Only over-fulfilled items are counted`, `Total output is compared with the total plan`],
    ex: `The assortment plan is a commitment to produce the right items. Over-fulfilment on one item does not offset a shortfall on another: a customer who needs item B will not take extra item A instead.`,
    why: [`Correct: min(actual, plan) for each item.`, `Over-fulfilment is not counted.`, `All items are included.`, `That is volume fulfilment, not assortment.`],
    trick: `“The lower of the two” — actual or plan.`, mistake: `Counting over-fulfilment.`, takeaway: `The assortment plan can never exceed 100% fulfilment.` } },
{ id: `out-3`, module: `output`, diff: `medium`, type: `calc`, correct: 2,
  ru: { q: `План выпуска по декадам — 200 / 200 / 200 изделий, факт — 150 / 210 / 260. Каков коэффициент ритмичности?`,
    o: [`1,033`, `0,750`, `0,917`, `0,950`],
    ex: `Засчитываем не выше плана: 150 + 200 + 200 = 550. Kритм = 550 / 600 = 0,917. Общий план выполнен на 103%, но выпуск был неритмичным: недовыпуск в начале и «штурм» в конце.`,
    why: [`Это выполнение плана по объёму (620 / 600) — сверхплан засчитан.`, `Учтена только первая декада.`, `Верно: 550 / 600.`, `Ошибка в отборе засчитываемых значений.`],
    trick: `Ритмичность не может быть выше 1.`, mistake: `Засчитывать перевыполнение в последней декаде.`, takeaway: `Выполнение плана в целом не гарантирует ритмичность.` },
  en: { q: `The output plan by ten-day periods is 200 / 200 / 200 units; actual is 150 / 210 / 260. What is the rhythm ratio?`,
    o: [`1.033`, `0.750`, `0.917`, `0.950`],
    ex: `Count no more than plan: 150 + 200 + 200 = 550. Kr = 550 / 600 = 0.917. The overall plan is 103% fulfilled, but output was irregular: a shortfall early and a rush at the end.`,
    why: [`That is volume fulfilment (620 / 600) — over-fulfilment counted.`, `Only the first period was used.`, `Correct: 550 / 600.`, `Wrong selection of counted values.`],
    trick: `The rhythm ratio can never exceed 1.`, mistake: `Counting over-fulfilment in the last period.`, takeaway: `Meeting the plan overall does not guarantee rhythm.` } },
{ id: `out-4`, module: `output`, diff: `medium`, type: `calc`, correct: 0,
  ru: { q: `Изделие А: план 100, факт 120; изделие Б: план 80, факт 60; изделие В: план 50, факт 50 (млн сум). Каково выполнение плана по ассортименту?`,
    o: [`91,3%`, `100,0%`, `108,7%`, `75,0%`],
    ex: `Засчитываем по каждой позиции не выше плана: 100 + 60 + 50 = 210. Kасс = 210 / 230 = 91,3%. По общему объёму план выполнен на 100% (230 / 230), но ассортиментное задание — нет.`,
    why: [`Верно: 210 / 230.`, `Это выполнение по общему объёму: перевыполнение А «прикрыло» недовыпуск Б.`, `Ошибочная база расчёта.`, `75% — выполнение только по изделию Б.`],
    trick: `Лишнее А не заменяет недостающее Б.`, mistake: `Путать выполнение по объёму и по ассортименту.`, takeaway: `Ассортиментный анализ показывает, выполнены ли обязательства перед покупателями.` },
  en: { q: `Product A: plan 100, actual 120; B: plan 80, actual 60; C: plan 50, actual 50 (m soums). What is the assortment plan fulfilment?`,
    o: [`91.3%`, `100.0%`, `108.7%`, `75.0%`],
    ex: `Count each item at no more than plan: 100 + 60 + 50 = 210. Ka = 210 / 230 = 91.3%. By total volume the plan is 100% met (230 / 230), but the assortment target is not.`,
    why: [`Correct: 210 / 230.`, `That is volume fulfilment: extra A “covered” the shortfall in B.`, `A wrong base.`, `75% is fulfilment for product B alone.`],
    trick: `Extra A does not replace missing B.`, mistake: `Confusing volume fulfilment with assortment fulfilment.`, takeaway: `Assortment analysis shows whether commitments to customers were met.` } },
{ id: `out-5`, module: `output`, diff: `hard`, type: `cause`, correct: 3,
  ru: { q: `Количество проданных изделий в натуральном выражении не изменилось, цены тоже, а выручка выросла на 8%. Какова наиболее вероятная причина?`,
    o: [`Ошибка учёта`, `Снижение себестоимости`, `Рост остатков готовой продукции`, `Структурный сдвиг: выросла доля более дорогих изделий в общем объёме продаж`],
    ex: `Выручка = Σ (количество × цена) по видам продукции. Если общее количество и цены каждого изделия неизменны, рост выручки возможен только за счёт структуры — продано больше дорогих и меньше дешёвых изделий.`,
    why: [`Есть экономическое объяснение — структурный сдвиг.`, `Себестоимость не входит в выручку.`, `Рост остатков уменьшил бы реализацию.`, `Верно: влияние структуры.`],
    trick: `Тот же объём, другая «корзина» — другая выручка.`, mistake: `Игнорировать структурный фактор в факторном анализе выручки.`, takeaway: `Выручку раскладывают на объём, структуру и цены.` },
  en: { q: `Units sold and prices are unchanged, yet revenue rose 8%. What is the most likely reason?`,
    o: [`An accounting error`, `Lower unit cost`, `Higher finished-goods stock`, `A mix shift: pricier products took a larger share of sales`],
    ex: `Revenue = Σ (quantity × price) by product. If total quantity and each product’s price are unchanged, revenue can rise only through the mix — more expensive items and fewer cheap ones were sold.`,
    why: [`There is an economic explanation — the mix.`, `Cost is not part of revenue.`, `Higher stock would reduce sales.`, `Correct: the mix effect.`],
    trick: `Same volume, different basket — different revenue.`, mistake: `Ignoring the mix factor in revenue analysis.`, takeaway: `Revenue is broken into volume, mix and prices.` } },
{ id: `out-6`, module: `output`, diff: `expert`, type: `case`, correct: 1,
  ru: { q: `План по объёму выполнен на 104%, коэффициент ритмичности — 0,82, доля брака выросла с 1,5% до 3,2%, сверхурочные удвоились. Как оценить работу цеха?`,
    o: [`Отлично: план перевыполнен`, `Формально план выполнен, но за счёт «штурмовщины»: неритмичный выпуск привёл к росту брака и сверхурочных, то есть к росту затрат и потере качества`, `Неудовлетворительно, так как план должен выполняться ровно на 100%`, `Оценка невозможна без данных о прибыли`],
    ex: `Показатели связаны: неритмичная работа означает простои в начале периода и перегрузку в конце, что вызывает брак и сверхурочные с повышенной оплатой. Итоговое перевыполнение достигнуто дорогой ценой. Резерв — равномерная загрузка через планирование снабжения и графиков.`,
    why: [`Объём без качества и затрат — неполная оценка.`, `Верно: видна причинно-следственная цепочка.`, `Перевыполнение плана само по себе не плохо.`, `Брак и сверхурочные уже показывают рост затрат.`],
    trick: `Ритмичность — причина, брак и сверхурочные — следствие.`, mistake: `Оценивать выпуск только по объёму.`, takeaway: `Хороший выпуск — объём + ассортимент + качество + ритмичность.` },
  en: { q: `The volume plan is 104% met, the rhythm ratio is 0.82, the defect rate rose from 1.5% to 3.2%, and overtime doubled. How should the workshop’s performance be assessed?`,
    o: [`Excellent: the plan was exceeded`, `The plan was met on paper, but through end-of-period rushing: irregular output led to more defects and overtime — higher costs and lower quality`, `Unsatisfactory, since a plan must be met at exactly 100%`, `It cannot be assessed without profit data`],
    ex: `The indicators are linked: irregular work means idle time early in the period and overload at the end, causing defects and premium-paid overtime. The over-fulfilment came at a high price. The reserve lies in even loading through better supply planning and schedules.`,
    why: [`Volume without quality and cost is an incomplete assessment.`, `Correct: the causal chain is clear.`, `Exceeding the plan is not bad in itself.`, `Defects and overtime already show rising costs.`],
    trick: `Rhythm is the cause; defects and overtime are the effects.`, mistake: `Judging output by volume alone.`, takeaway: `Good output = volume + assortment + quality + rhythm.` } },

/* ── 13 · Финансовая устойчивость ────────────────────────────────────────── */
{ id: `st-1`, module: `stability`, diff: `easy`, type: `concept`, correct: 0,
  ru: { q: `Как рассчитывается коэффициент автономии (финансовой независимости)?`,
    o: [`Собственный капитал / Валюта баланса`, `Заёмный капитал / Собственный капитал`, `Оборотные активы / Краткосрочные обязательства`, `Собственный капитал / Заёмный капитал`],
    ex: `Коэффициент автономии показывает долю собственного капитала в общей сумме источников. Ориентир — не ниже 0,5: тогда большая часть имущества профинансирована собственниками.`,
    why: [`Верно.`, `Это коэффициент капитализации (финансового левериджа).`, `Это текущая ликвидность.`, `Это коэффициент финансирования (обратный капитализации).`],
    trick: `Автономия — «какая доля всего — своя».`, mistake: `Путать автономию и капитализацию.`, takeaway: `Чем выше автономия, тем меньше зависимость от кредиторов.` },
  en: { q: `How is the autonomy (equity) ratio calculated?`,
    o: [`Equity / Total assets`, `Debt / Equity`, `Current assets / Current liabilities`, `Equity / Debt`],
    ex: `The autonomy ratio shows equity’s share of total funding. The benchmark is at least 0.5: then most assets are financed by owners.`,
    why: [`Correct.`, `That is the leverage (capitalisation) ratio.`, `That is the current ratio.`, `That is the financing ratio (inverse of leverage).`],
    trick: `Autonomy — “what share of the whole is ours”.`, mistake: `Confusing autonomy with leverage.`, takeaway: `Higher autonomy means less dependence on creditors.` } },
{ id: `st-2`, module: `stability`, diff: `easy`, type: `concept`, correct: 2,
  ru: { q: `Чем коэффициент быстрой ликвидности отличается от текущей?`,
    o: [`В числитель добавляются внеоборотные активы`, `В знаменатель включаются долгосрочные обязательства`, `Из оборотных активов исключаются запасы — наименее ликвидная часть`, `Учитываются только денежные средства`],
    ex: `Запасы превращаются в деньги дольше всего: их нужно переработать, продать и дождаться оплаты. Быстрая ликвидность показывает, сможет ли предприятие расплатиться по текущим долгам без распродажи запасов. Только деньги и краткосрочные вложения учитывает абсолютная ликвидность.`,
    why: [`Внеоборотные активы в ликвидность не включают.`, `Знаменатель — краткосрочные обязательства во всех трёх коэффициентах.`, `Верно: (ОА − запасы) / КО.`, `Это абсолютная ликвидность.`],
    trick: `Текущая — всё оборотное, быстрая — без запасов, абсолютная — только деньги.`, mistake: `Включать запасы в быструю ликвидность.`, takeaway: `Три коэффициента ликвидности — три «скорости» погашения долгов.` },
  en: { q: `How does the quick ratio differ from the current ratio?`,
    o: [`Non-current assets are added to the numerator`, `Long-term liabilities are added to the denominator`, `Inventory — the least liquid part — is excluded from current assets`, `Only cash is counted`],
    ex: `Inventory takes longest to turn into cash: it must be processed, sold and paid for. The quick ratio shows whether the company can pay current debts without selling off inventory. The cash ratio counts only cash and short-term investments.`,
    why: [`Non-current assets are never part of liquidity ratios.`, `The denominator is current liabilities in all three ratios.`, `Correct: (CA − inventory) / CL.`, `That is the cash ratio.`],
    trick: `Current — all current assets; quick — minus inventory; cash — cash only.`, mistake: `Including inventory in the quick ratio.`, takeaway: `Three liquidity ratios — three “speeds” of paying debts.` } },
{ id: `st-3`, module: `stability`, diff: `medium`, type: `calc`, correct: 1,
  ru: { q: `Оборотные активы — 4 800, в том числе запасы 1 800 и денежные средства 400; краткосрочные обязательства — 3 000 (млн сум). Каков коэффициент быстрой ликвидности?`,
    o: [`1,60`, `1,00`, `0,13`, `0,60`],
    ex: `Быстрая ликвидность = (4 800 − 1 800) / 3 000 = 1,00. Текущая = 4 800 / 3 000 = 1,60, абсолютная = 400 / 3 000 ≈ 0,13.`,
    why: [`Это текущая ликвидность.`, `Верно: (4 800 − 1 800) / 3 000.`, `Это абсолютная ликвидность.`, `Запасы разделены на обязательства — бессмысленное отношение.`],
    trick: `Быстрая = (ОА − запасы) / КО.`, mistake: `Путать три коэффициента ликвидности.`, takeaway: `Значение около 1 — без продажи запасов долги покрываются.` },
  en: { q: `Current assets 4,800, including inventory 1,800 and cash 400; current liabilities 3,000 (m soums). What is the quick ratio?`,
    o: [`1.60`, `1.00`, `0.13`, `0.60`],
    ex: `Quick ratio = (4,800 − 1,800) / 3,000 = 1.00. Current ratio = 4,800 / 3,000 = 1.60; cash ratio = 400 / 3,000 ≈ 0.13.`,
    why: [`That is the current ratio.`, `Correct: (4,800 − 1,800) / 3,000.`, `That is the cash ratio.`, `Inventory over liabilities — a meaningless ratio.`],
    trick: `Quick = (CA − inventory) / CL.`, mistake: `Mixing up the three liquidity ratios.`, takeaway: `Around 1 — debts are covered without selling inventory.` } },
{ id: `st-4`, module: `stability`, diff: `medium`, type: `calc`, correct: 3,
  ru: { q: `Собственный капитал — 6 000, заёмный — 4 000 млн сум. Каков коэффициент капитализации (финансового левериджа)?`,
    o: [`0,60`, `1,50`, `0,40`, `0,67`],
    ex: `Kк = ЗК / СК = 4 000 / 6 000 = 0,67 — на сум собственных средств приходится 67 тийинов заёмных. Ориентир — не выше 1. Коэффициент автономии здесь 0,6.`,
    why: [`0,60 — коэффициент автономии (6 000 / 10 000).`, `1,50 — обратное отношение (СК / ЗК).`, `0,40 — коэффициент финансовой зависимости (ЗК / ВБ).`, `Верно: 4 000 / 6 000.`],
    trick: `Капитализация — «чужое к своему».`, mistake: `Путать знаменатель: СК, а не валюта баланса.`, takeaway: `Капитализация ниже 1 — заёмных средств меньше собственных.` },
  en: { q: `Equity is 6,000 and debt 4,000 m soums. What is the leverage (capitalisation) ratio?`,
    o: [`0.60`, `1.50`, `0.40`, `0.67`],
    ex: `Kl = Debt / Equity = 4,000 / 6,000 = 0.67 — each soum of equity carries 0.67 soums of debt. The benchmark is at most 1. The autonomy ratio here is 0.6.`,
    why: [`0.60 is the autonomy ratio (6,000 / 10,000).`, `1.50 is the inverse (Equity / Debt).`, `0.40 is the dependency ratio (Debt / Total).`, `Correct: 4,000 / 6,000.`],
    trick: `Leverage — “theirs over ours”.`, mistake: `Using total assets instead of equity as the base.`, takeaway: `Leverage below 1 means less debt than equity.` } },
{ id: `st-5`, module: `stability`, diff: `hard`, type: `case`, correct: 2,
  ru: { q: `Текущая ликвидность — 2,4, но абсолютная — 0,03; запасы составляют 70% оборотных активов, и их оборачиваемость замедлилась. Как оценить платёжеспособность?`,
    o: [`Высокая: текущая ликвидность выше ориентира 2`, `Высокая: все коэффициенты в норме`, `Формально высокая, но качество оборотных активов низкое: ликвидность держится на медленно продающихся запасах, а денег почти нет — реальный риск кассовых разрывов`, `Низкая, так как текущая ликвидность выше 2,5`],
    ex: `Структура оборотных активов важнее итогового коэффициента. Если 70% приходится на запасы с замедляющимся оборотом, превратить их в деньги быстро не удастся. Абсолютная ликвидность 0,03 означает, что за счёт денег можно погасить лишь 3% текущих долгов.`,
    why: [`Один коэффициент не даёт полной картины.`, `Абсолютная ликвидность намного ниже ориентира 0,2.`, `Верно: смотрите на структуру и качество активов.`, `Текущая ликвидность 2,4 в пределах ориентира.`],
    trick: `Неликвидные запасы делают «хорошую» ликвидность иллюзией.`, mistake: `Делать вывод по одному коэффициенту.`, takeaway: `Анализируйте все три коэффициента ликвидности вместе со структурой активов.` },
  en: { q: `The current ratio is 2.4, but the cash ratio is 0.03; inventory is 70% of current assets and its turnover has slowed. How should solvency be assessed?`,
    o: [`High: the current ratio exceeds the benchmark of 2`, `High: all ratios are within norms`, `High on paper, but asset quality is poor: liquidity rests on slow-moving inventory and there is almost no cash — a real risk of cash gaps`, `Low, because the current ratio exceeds 2.5`],
    ex: `The structure of current assets matters more than the headline ratio. If 70% is slow-moving inventory, it cannot be turned into cash quickly. A cash ratio of 0.03 means cash covers only 3% of current debts.`,
    why: [`One ratio does not give the full picture.`, `The cash ratio is far below the 0.2 benchmark.`, `Correct: look at the structure and quality of assets.`, `A current ratio of 2.4 is within the benchmark range.`],
    trick: `Illiquid inventory makes “good” liquidity an illusion.`, mistake: `Concluding from a single ratio.`, takeaway: `Read all three liquidity ratios together with the asset structure.` } },
{ id: `st-6`, module: `stability`, diff: `expert`, type: `case`, correct: 1,
  ru: { q: `Определите тип финансовой устойчивости по обеспеченности запасов источниками формирования.`,
    ctx: { head: [`Показатель`, `млн сум`], rows: [[`Запасы`, `3 000`], [`Собственные оборотные средства (СОС)`, `1 200`], [`Долгосрочные обязательства`, `1 000`], [`Краткосрочные кредиты и займы`, `1 500`]] },
    o: [`Абсолютная устойчивость`, `Неустойчивое финансовое состояние`, `Нормальная устойчивость`, `Кризисное финансовое состояние`],
    ex: `Сравниваем запасы с источниками по нарастающей: СОС = 1 200 < 3 000 — абсолютной устойчивости нет. СОС + ДО = 2 200 < 3 000 — нормальной тоже нет. СОС + ДО + краткосрочные кредиты = 3 700 ≥ 3 000 — запасы покрыты с привлечением краткосрочных кредитов. Это неустойчивое состояние: платёжеспособность сохраняется, но зависит от кредиторов.`,
    why: [`Запасы не покрываются только СОС.`, `Верно: покрытие достигается лишь с краткосрочными кредитами.`, `Для нормальной устойчивости хватило бы СОС и долгосрочных источников.`, `Кризис — когда не хватает даже всех трёх источников.`],
    trick: `Ступени: СОС → + долгосрочные → + краткосрочные → кризис.`, mistake: `Сравнивать запасы только с одним источником.`, takeaway: `Тип устойчивости определяется тем, какой «ступенью» источников покрыты запасы.` },
  en: { q: `Determine the type of financial stability by how inventory is covered by funding sources.`,
    ctx: { head: [`Item`, `m soums`], rows: [[`Inventory`, `3,000`], [`Own working capital (OWC)`, `1,200`], [`Long-term liabilities`, `1,000`], [`Short-term loans`, `1,500`]] },
    o: [`Absolute stability`, `Unstable financial position`, `Normal stability`, `Crisis`],
    ex: `Compare inventory with cumulative sources: OWC = 1,200 < 3,000 — not absolute. OWC + LTL = 2,200 < 3,000 — not normal. OWC + LTL + short-term loans = 3,700 ≥ 3,000 — inventory is covered only with short-term loans. This is an unstable position: solvency holds, but depends on lenders.`,
    why: [`OWC alone does not cover inventory.`, `Correct: coverage is reached only with short-term loans.`, `Normal stability would need only OWC and long-term sources.`, `Crisis is when even all three sources fall short.`],
    trick: `Steps: OWC → + long-term → + short-term → crisis.`, mistake: `Comparing inventory with only one source.`, takeaway: `The stability type depends on which “step” of sources covers inventory.` } },

/* ── 14 · Точка безубыточности ───────────────────────────────────────────── */
{ id: `be-1`, module: `breakeven`, diff: `easy`, type: `concept`, correct: 3,
  ru: { q: `Что такое маржинальный доход?`,
    o: [`Выручка минус все затраты`, `Прибыль после уплаты налогов`, `Выручка минус постоянные затраты`, `Выручка минус переменные затраты`],
    ex: `Маржинальный доход — часть выручки, остающаяся после покрытия переменных затрат. Из него покрываются постоянные затраты, а остаток — прибыль.`,
    why: [`Это прибыль (до налогообложения).`, `Это чистая прибыль.`, `Постоянные затраты вычитаются из маржинального дохода, а не из выручки.`, `Верно.`],
    trick: `Маржа — «вклад» в покрытие постоянных затрат.`, mistake: `Вычитать постоянные затраты при расчёте маржи.`, takeaway: `Маржинальный доход − постоянные затраты = прибыль.` },
  en: { q: `What is the contribution margin?`,
    o: [`Revenue minus all costs`, `Profit after tax`, `Revenue minus fixed costs`, `Revenue minus variable costs`],
    ex: `The contribution margin is the part of revenue left after covering variable costs. It covers fixed costs, and the remainder is profit.`,
    why: [`That is profit (before tax).`, `That is net profit.`, `Fixed costs are deducted from the margin, not from revenue.`, `Correct.`],
    trick: `Contribution — the “contribution” towards fixed costs.`, mistake: `Deducting fixed costs when calculating the margin.`, takeaway: `Contribution margin − fixed costs = profit.` } },
{ id: `be-2`, module: `breakeven`, diff: `easy`, type: `calc`, correct: 1,
  ru: { q: `Постоянные затраты — 400 млн сум, цена — 25 тыс. сум, переменные затраты — 15 тыс. сум на изделие. Какова точка безубыточности в натуральном выражении?`,
    o: [`16 000 изделий`, `40 000 изделий`, `26 667 изделий`, `10 000 изделий`],
    ex: `Q* = FC / (p − v) = 400 000 тыс. / (25 − 15) тыс. = 40 000 изделий. Каждое изделие приносит 10 тыс. сум маржи; чтобы покрыть 400 млн, нужно 40 000 изделий.`,
    why: [`Постоянные затраты разделены на цену, а не на маржу.`, `Верно.`, `Постоянные затраты разделены на переменные.`, `Цена и маржа перепутаны в другом соотношении.`],
    trick: `Сколько «кирпичиков маржи» нужно, чтобы построить стену постоянных затрат.`, mistake: `Делить на цену вместо маржи на единицу.`, takeaway: `Q* = FC / маржа на единицу.` },
  en: { q: `Fixed costs are 400 m soums, the price is 25 thousand soums and variable cost 15 thousand per unit. What is the break-even point in units?`,
    o: [`16,000 units`, `40,000 units`, `26,667 units`, `10,000 units`],
    ex: `Q* = FC / (p − v) = 400,000 thousand / (25 − 15) thousand = 40,000 units. Each unit contributes 10 thousand; covering 400 m takes 40,000 units.`,
    why: [`Fixed costs divided by price, not by unit margin.`, `Correct.`, `Fixed costs divided by variable cost.`, `Another mix-up of price and margin.`],
    trick: `How many “bricks of margin” build the wall of fixed costs.`, mistake: `Dividing by price instead of unit margin.`, takeaway: `Q* = FC / unit margin.` } },
{ id: `be-3`, module: `breakeven`, diff: `medium`, type: `calc`, correct: 0,
  ru: { q: `Фактическая выручка — 2 000 млн сум, выручка в точке безубыточности — 1 500 млн сум. Каков запас финансовой прочности?`,
    o: [`25%`, `33%`, `75%`, `500%`],
    ex: `ЗФП = (2 000 − 1 500) / 2 000 × 100% = 25%. Выручка может снизиться на четверть, прежде чем предприятие станет убыточным. В деньгах запас — 500 млн сум.`,
    why: [`Верно: 500 / 2 000.`, `База — фактическая выручка, а не порог (500 / 1 500).`, `75% — доля порога в выручке.`, `Смешаны деньги и проценты.`],
    trick: `Запас прочности — «сколько можно потерять» относительно текущей выручки.`, mistake: `Делить на выручку в точке безубыточности.`, takeaway: `Чем больше запас прочности, тем ниже операционный риск.` },
  en: { q: `Actual revenue is 2,000 m soums and break-even revenue 1,500 m soums. What is the margin of safety?`,
    o: [`25%`, `33%`, `75%`, `500%`],
    ex: `MS = (2,000 − 1,500) / 2,000 × 100% = 25%. Revenue can fall by a quarter before the company makes a loss. In money terms the margin is 500 m soums.`,
    why: [`Correct: 500 / 2,000.`, `The base is actual revenue, not break-even (500 / 1,500).`, `75% is break-even as a share of revenue.`, `Money and percentages mixed up.`],
    trick: `Margin of safety — “how much you can lose” relative to current revenue.`, mistake: `Dividing by break-even revenue.`, takeaway: `The larger the margin of safety, the lower the operating risk.` } },
{ id: `be-4`, module: `breakeven`, diff: `medium`, type: `calc`, correct: 2,
  ru: { q: `Маржинальный доход — 900 млн сум, прибыль — 300 млн сум. На сколько процентов вырастет прибыль, если выручка вырастет на 10% (структура затрат неизменна)?`,
    o: [`На 10%`, `На 3%`, `На 30%`, `На 90%`],
    ex: `Операционный рычаг ОР = МД / Прибыль = 900 / 300 = 3. ΔПрибыли = 3 × 10% = 30%. Проверка: МД вырастет на 90 (до 990), прибыль — до 390, то есть на 30%.`,
    why: [`Без рычага прибыль росла бы как выручка — но постоянные затраты не растут.`, `Деление вместо умножения.`, `Верно: 3 × 10%.`, `Перепутаны прирост и маржа.`],
    trick: `Рычаг умножает процент изменения выручки.`, mistake: `Считать, что прибыль меняется в той же пропорции, что и выручка.`, takeaway: `Высокий рычаг — высокая чувствительность прибыли в обе стороны.` },
  en: { q: `The contribution margin is 900 m soums and profit 300 m soums. By what percentage will profit rise if revenue rises 10% (same cost structure)?`,
    o: [`10%`, `3%`, `30%`, `90%`],
    ex: `Operating leverage DOL = CM / Profit = 900 / 300 = 3. ΔProfit = 3 × 10% = 30%. Check: CM rises by 90 (to 990), profit to 390 — up 30%.`,
    why: [`Without leverage profit would track revenue — but fixed costs do not grow.`, `Division instead of multiplication.`, `Correct: 3 × 10%.`, `Growth and margin confused.`],
    trick: `Leverage multiplies the percentage change in revenue.`, mistake: `Assuming profit changes in proportion to revenue.`, takeaway: `High leverage means high profit sensitivity both ways.` } },
{ id: `be-5`, module: `breakeven`, diff: `hard`, type: `cause`, correct: 0,
  ru: { q: `Предприятие заменило ручной труд автоматической линией: постоянные затраты выросли, переменные на единицу снизились. Как это повлияет на точку безубыточности и операционный рычаг при прежних объёмах?`,
    o: [`Как правило, точка безубыточности и операционный рычаг растут: прибыль становится чувствительнее к объёму, растёт и потенциальная прибыль при росте продаж, и риск при их падении`, `Точка безубыточности снизится, рычаг упадёт`, `Ничего не изменится, если выручка та же`, `Рычаг снизится, так как переменные затраты уменьшились`],
    ex: `Рост постоянных затрат поднимает порог, который нужно перекрыть маржей. Одновременно маржа на единицу растёт, поэтому каждое дополнительное изделие сверх порога приносит больше прибыли. Итог — более высокий рычаг: в хорошие времена прибыль растёт быстрее, в плохие — быстрее падает.`,
    why: [`Верно: больше постоянных затрат — сильнее рычаг.`, `Знак изменения обратный.`, `Структура затрат меняет и порог, и чувствительность.`, `Рычаг определяется отношением маржи к прибыли, а при росте постоянных затрат прибыль относительно маржи снижается.`],
    trick: `Автоматизация меняет «переменное» на «постоянное» — и усиливает рычаг.`, mistake: `Оценивать автоматизацию только по снижению затрат на единицу.`, takeaway: `Структура затрат определяет операционный риск.` },
  en: { q: `A company replaced manual labour with an automated line: fixed costs rose and variable cost per unit fell. At the same volumes, how are break-even and operating leverage affected?`,
    o: [`Typically both break-even and operating leverage rise: profit becomes more sensitive to volume — greater upside if sales grow, more risk if they fall`, `Break-even falls and leverage falls`, `Nothing changes if revenue is the same`, `Leverage falls because variable costs fell`],
    ex: `Higher fixed costs raise the threshold that the margin must cover. At the same time the unit margin grows, so each unit beyond break-even earns more. The result is higher leverage: profit rises faster in good times and falls faster in bad ones.`,
    why: [`Correct: more fixed costs — stronger leverage.`, `The direction is reversed.`, `The cost structure changes both the threshold and sensitivity.`, `Leverage is margin over profit, and with higher fixed costs profit shrinks relative to margin.`],
    trick: `Automation turns “variable” into “fixed” — and strengthens leverage.`, mistake: `Judging automation only by lower unit cost.`, takeaway: `Cost structure determines operating risk.` } },
{ id: `be-6`, module: `breakeven`, diff: `expert`, type: `calc`, correct: 2,
  ru: { q: `Постоянные затраты — 300 млн сум, цена — 40 тыс. сум, переменные затраты — 25 тыс. сум на изделие. Сколько изделий нужно продать, чтобы получить прибыль 150 млн сум?`,
    o: [`20 000 изделий`, `10 000 изделий`, `30 000 изделий`, `11 250 изделий`],
    ex: `Q = (FC + Прибыль) / (p − v) = (300 000 + 150 000) тыс. / 15 тыс. = 30 000 изделий. 20 000 — точка безубыточности: первые 20 000 изделий покрывают постоянные затраты, следующие 10 000 приносят прибыль 150 млн.`,
    why: [`Это точка безубыточности — прибыль в ней равна нулю.`, `Это только изделия сверх точки безубыточности.`, `Верно: (300 + 150) / 15 тыс.`, `Сумма разделена на цену вместо маржи.`],
    trick: `Целевая прибыль — это «ещё одни постоянные затраты» в числителе.`, mistake: `Забывать, что сначала нужно покрыть постоянные затраты.`, takeaway: `Q = (FC + целевая прибыль) / маржа на единицу.` },
  en: { q: `Fixed costs are 300 m soums, the price 40 thousand and variable cost 25 thousand per unit. How many units must be sold to earn a profit of 150 m soums?`,
    o: [`20,000 units`, `10,000 units`, `30,000 units`, `11,250 units`],
    ex: `Q = (FC + Profit) / (p − v) = (300,000 + 150,000) thousand / 15 thousand = 30,000 units. 20,000 is break-even: the first 20,000 units cover fixed costs, the next 10,000 earn the 150 m profit.`,
    why: [`That is break-even — profit there is zero.`, `That is only the units beyond break-even.`, `Correct: (300 + 150) / 15 thousand.`, `The total was divided by price instead of unit margin.`],
    trick: `Target profit is “one more fixed cost” in the numerator.`, mistake: `Forgetting that fixed costs must be covered first.`, takeaway: `Q = (FC + target profit) / unit margin.` } },

/* ── 15 · Финансовые результаты ──────────────────────────────────────────── */
{ id: `res-1`, module: `results`, diff: `easy`, type: `concept`, correct: 1,
  ru: { q: `Как определяется валовая прибыль?`,
    o: [`Выручка минус все расходы предприятия`, `Чистая выручка минус себестоимость реализованной продукции`, `Прибыль до налогообложения минус налог`, `Выручка минус расходы периода`],
    ex: `Валовая прибыль — первая ступень «лестницы» прибыли: разница между чистой выручкой и производственной себестоимостью проданной продукции. Затем вычитаются расходы периода, финансовые расходы и налог.`,
    why: [`Это итоговый результат, а не валовая прибыль.`, `Верно.`, `Это чистая прибыль.`, `Себестоимость реализованной продукции не вычтена.`],
    trick: `Валовая — «грубая» прибыль: только выручка и себестоимость.`, mistake: `Вычитать на первой ступени все расходы сразу.`, takeaway: `Каждая ступень лестницы прибыли вычитает свою группу расходов.` },
  en: { q: `How is gross profit determined?`,
    o: [`Revenue minus all expenses`, `Net revenue minus cost of goods sold`, `Profit before tax minus tax`, `Revenue minus period expenses`],
    ex: `Gross profit is the first step of the profit ladder: net revenue minus the production cost of goods sold. Then period expenses, finance costs and tax are deducted.`,
    why: [`That is the final result, not gross profit.`, `Correct.`, `That is net profit.`, `Cost of goods sold was not deducted.`],
    trick: `Gross — “rough” profit: just revenue and cost of sales.`, mistake: `Deducting every expense at the first step.`, takeaway: `Each step of the ladder deducts its own group of expenses.` } },
{ id: `res-2`, module: `results`, diff: `easy`, type: `compare`, correct: 0,
  ru: { q: `Чем рентабельность продаж отличается от рентабельности продукции?`,
    o: [`Рентабельность продаж — прибыль к выручке, рентабельность продукции — прибыль к себестоимости (затратам)`, `Это одно и то же`, `Рентабельность продаж — прибыль к активам`, `Рентабельность продукции — выручка к себестоимости`],
    ex: `Оба показателя используют прибыль от продаж, но разную базу. Рентабельность продаж показывает долю прибыли в каждом суме выручки, рентабельность продукции — прибыль на каждый сум затрат. Поэтому рентабельность продукции всегда выше рентабельности продаж при прибыльной работе.`,
    why: [`Верно: разная база.`, `Базы разные — и значения разные.`, `Прибыль к активам — ROA.`, `Выручка к себестоимости — не рентабельность.`],
    trick: `Продаж — «к выручке», продукции — «к затратам».`, mistake: `Путать базу расчёта.`, takeaway: `Всегда уточняйте знаменатель показателя рентабельности.` },
  en: { q: `How does return on sales differ from return on costs?`,
    o: [`Return on sales is profit over revenue; return on costs is profit over cost`, `They are the same`, `Return on sales is profit over assets`, `Return on costs is revenue over cost`],
    ex: `Both use operating profit but different bases. Return on sales shows the profit in each soum of revenue; return on costs shows profit per soum of cost. So when the business is profitable, return on costs is always higher than return on sales.`,
    why: [`Correct: different bases.`, `Different bases — different values.`, `Profit over assets is ROA.`, `Revenue over cost is not a profitability ratio.`],
    trick: `Sales — “over revenue”; costs — “over spending”.`, mistake: `Confusing the base.`, takeaway: `Always check the denominator of a profitability ratio.` } },
{ id: `res-3`, module: `results`, diff: `medium`, type: `calc`, correct: 2,
  ru: { q: `Выручка — 8 000, себестоимость реализованной продукции — 5 600, расходы периода — 1 200 млн сум. Какова рентабельность продаж по прибыли от основной деятельности?`,
    o: [`30,0%`, `21,4%`, `15,0%`, `17,6%`],
    ex: `Валовая прибыль = 8 000 − 5 600 = 2 400. Операционная прибыль = 2 400 − 1 200 = 1 200. ROS = 1 200 / 8 000 = 15,0%.`,
    why: [`30% — валовая рентабельность (2 400 / 8 000).`, `21,4% — прибыль к производственной себестоимости (1 200 / 5 600).`, `Верно: 1 200 / 8 000.`, `17,6% — рентабельность продукции к полной себестоимости (1 200 / 6 800).`],
    trick: `Сначала пройдите лестницу прибыли, потом делите на выручку.`, mistake: `Использовать валовую прибыль вместо операционной.`, takeaway: `Рентабельность продаж — прибыль от продаж на сум выручки.` },
  en: { q: `Revenue 8,000, cost of goods sold 5,600, period expenses 1,200 m soums. What is return on sales based on operating profit?`,
    o: [`30.0%`, `21.4%`, `15.0%`, `17.6%`],
    ex: `Gross profit = 8,000 − 5,600 = 2,400. Operating profit = 2,400 − 1,200 = 1,200. ROS = 1,200 / 8,000 = 15.0%.`,
    why: [`30% is gross margin (2,400 / 8,000).`, `21.4% is profit over production cost (1,200 / 5,600).`, `Correct: 1,200 / 8,000.`, `17.6% is return on total cost (1,200 / 6,800).`],
    trick: `Walk down the profit ladder first, then divide by revenue.`, mistake: `Using gross profit instead of operating profit.`, takeaway: `Return on sales is operating profit per soum of revenue.` } },
{ id: `res-4`, module: `results`, diff: `medium`, type: `calc`, correct: 3,
  ru: { q: `Продано 1 000 изделий. Цена выросла с 50 до 54 тыс. сум. Каково влияние изменения цены на прибыль от продаж?`,
    o: [`+4 тыс. сум`, `+54 000 тыс. сум`, `+400 тыс. сум`, `+4 000 тыс. сум (4 млн сум)`],
    ex: `ΔП(цена) = (p₁ − p₀) × q₁ = (54 − 50) × 1 000 = 4 000 тыс. сум. Рост цены целиком увеличивает прибыль, если себестоимость не изменилась.`,
    why: [`Не умножено на количество.`, `Это вся выручка по новой цене.`, `Ошибка на порядок.`, `Верно: 4 × 1 000.`],
    trick: `Цена влияет на прибыль «один к одному» — по фактическому объёму.`, mistake: `Умножать изменение цены на базисный объём.`, takeaway: `Влияние цены рассчитывают по фактическому количеству продаж.` },
  en: { q: `1,000 units were sold. The price rose from 50 to 54 thousand soums. What is the effect of the price change on operating profit?`,
    o: [`+4 thousand soums`, `+54,000 thousand soums`, `+400 thousand soums`, `+4,000 thousand soums (4 m soums)`],
    ex: `ΔP(price) = (p₁ − p₀) × q₁ = (54 − 50) × 1,000 = 4,000 thousand soums. A price rise goes straight to profit if cost is unchanged.`,
    why: [`Not multiplied by quantity.`, `That is total revenue at the new price.`, `An order-of-magnitude error.`, `Correct: 4 × 1,000.`],
    trick: `Price hits profit one-for-one — at actual volume.`, mistake: `Multiplying the price change by base volume.`, takeaway: `The price effect uses actual quantity sold.` } },
{ id: `res-5`, module: `results`, diff: `hard`, type: `calc`, correct: 1,
  ru: { q: `Рентабельность продаж снизилась с 12% до 10%, а оборачиваемость активов выросла с 1,2 до 1,5. Как изменилась рентабельность активов (ROA = ROS × оборачиваемость)?`,
    o: [`Снизилась с 14,4% до 10%`, `Выросла с 14,4% до 15,0%`, `Не изменилась`, `Снизилась на 2 п.п.`],
    ex: `ROA₀ = 12% × 1,2 = 14,4%; ROA₁ = 10% × 1,5 = 15,0%. Несмотря на падение маржи, активы стали работать быстрее, и их отдача выросла на 0,6 п.п.`,
    why: [`Не учтён рост оборачиваемости.`, `Верно: 14,4% → 15,0%.`, `Факторы изменились не взаимоуничтожающе.`, `Это изменение только рентабельности продаж.`],
    trick: `Маржа × скорость — меньше маржи, но больше оборотов.`, mistake: `Делать вывод по одному фактору.`, takeaway: `Падение маржи можно компенсировать ускорением оборота.` },
  en: { q: `Return on sales fell from 12% to 10%, while asset turnover rose from 1.2 to 1.5. How did return on assets change (ROA = ROS × turnover)?`,
    o: [`It fell from 14.4% to 10%`, `It rose from 14.4% to 15.0%`, `It did not change`, `It fell 2 p.p.`],
    ex: `ROA₀ = 12% × 1.2 = 14.4%; ROA₁ = 10% × 1.5 = 15.0%. Despite the lower margin, assets worked faster and their return rose 0.6 p.p.`,
    why: [`The higher turnover was ignored.`, `Correct: 14.4% → 15.0%.`, `The factors did not cancel out.`, `That is the change in ROS alone.`],
    trick: `Margin × speed — a smaller margin but more turns.`, mistake: `Concluding from one factor.`, takeaway: `A lower margin can be offset by faster turnover.` } },
{ id: `res-6`, module: `results`, diff: `expert`, type: `case`, correct: 0,
  ru: { q: `Чистая прибыль выросла на 20%, а прибыль от основной деятельности снизилась на 15%. В прочих доходах отражена продажа земельного участка. Как оценить финансовые результаты?`,
    o: [`Качество прибыли ухудшилось: рост обеспечен разовым доходом, а основная деятельность стала менее прибыльной — нужен анализ причин падения операционной прибыли`, `Результаты улучшились, поскольку растёт чистая прибыль`, `Результаты не изменились: рост и падение компенсируют друг друга`, `Нужно анализировать только чистую прибыль — остальное вторично`],
    ex: `Устойчивость прибыли определяется основной деятельностью. Продажа участка — разовое событие, которое не повторится. Снижение операционной прибыли на 15% — главный сигнал: нужно разложить его на объём, структуру, цены и себестоимость.`,
    why: [`Верно: разовый доход маскирует ухудшение.`, `Итог без структуры обманчив.`, `Компенсация разовая — в следующем году её не будет.`, `Именно структура прибыли показывает её качество.`],
    trick: `Чистая прибыль — витрина, операционная — фундамент.`, mistake: `Радоваться росту чистой прибыли, не глядя на источники.`, takeaway: `Разовые доходы отделяют при оценке устойчивости результатов.` },
  en: { q: `Net profit rose 20%, while operating profit fell 15%. Other income includes the sale of a land plot. How should the financial results be assessed?`,
    o: [`Earnings quality has worsened: growth came from a one-off gain while the core business became less profitable — the fall in operating profit needs analysis`, `Results improved, since net profit is up`, `Results are unchanged: the rise and fall cancel out`, `Only net profit matters — the rest is secondary`],
    ex: `Sustainable profit comes from core operations. The land sale is a one-off that will not recur. The 15% fall in operating profit is the main signal: it should be broken down into volume, mix, prices and cost.`,
    why: [`Correct: a one-off gain masks deterioration.`, `A bottom line without structure misleads.`, `The offset is one-off — it will not recur next year.`, `The structure of profit is exactly what shows its quality.`],
    trick: `Net profit is the shop window; operating profit is the foundation.`, mistake: `Celebrating higher net profit without checking its sources.`, takeaway: `Separate one-off income when judging the sustainability of results.` } }
);
